use crate::aap::caps::state_read;

struct Node;

/// Keys tried, in order, in the 'subscriptions' store.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // The node's sole authority is StateHandle<'subscriptions', read>.
        // No filesystem or HTTP capability is granted, so no logging or
        // enrichment calls are made here.
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_urls(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        SubscriptionList { urls: Vec::new() }
    }
}

/// Accepts either a JSON array of strings, or newline/comma-separated text
/// (blank lines and `#` comments ignored). Result is trimmed and de-duplicated
/// in first-seen order.
fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') {
        parse_json_string_array(trimmed).unwrap_or_default()
    } else {
        trimmed
            .split(|c| c == '\n' || c == '\r' || c == ',')
            .map(|s| s.trim())
            .filter(|s| !s.is_empty() && !s.starts_with('#'))
            .map(|s| s.to_string())
            .collect()
    };

    let mut out: Vec<String> = Vec::new();
    for c in candidates {
        let c = c.trim().to_string();
        if !c.is_empty() && !out.contains(&c) {
            out.push(c);
        }
    }
    out
}

fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    let skip_ws = |i: &mut usize| {
        while *i < chars.len() && chars[*i].is_whitespace() {
            *i += 1;
        }
    };
    skip_ws(&mut i);
    if chars.get(i) != Some(&'[') {
        return None;
    }
    i += 1;
    let mut out = Vec::new();
    skip_ws(&mut i);
    if chars.get(i) == Some(&']') {
        return Some(out);
    }
    loop {
        skip_ws(&mut i);
        if chars.get(i) != Some(&'"') {
            return None;
        }
        i += 1;
        let mut buf = String::new();
        loop {
            let c = *chars.get(i)?;
            i += 1;
            match c {
                '"' => break,
                '\\' => {
                    let e = *chars.get(i)?;
                    i += 1;
                    match e {
                        '"' => buf.push('"'),
                        '\\' => buf.push('\\'),
                        '/' => buf.push('/'),
                        'b' => buf.push('\u{8}'),
                        'f' => buf.push('\u{c}'),
                        'n' => buf.push('\n'),
                        'r' => buf.push('\r'),
                        't' => buf.push('\t'),
                        'u' => {
                            let hi = read_hex4(&chars, &mut i)?;
                            let cp = if (0xD800..0xDC00).contains(&hi) {
                                if chars.get(i) == Some(&'\\') && chars.get(i + 1) == Some(&'u') {
                                    i += 2;
                                    let lo = read_hex4(&chars, &mut i)?;
                                    if !(0xDC00..0xE000).contains(&lo) {
                                        return None;
                                    }
                                    0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00)
                                } else {
                                    return None;
                                }
                            } else {
                                hi
                            };
                            buf.push(char::from_u32(cp)?);
                        }
                        _ => return None,
                    }
                }
                _ => buf.push(c),
            }
        }
        out.push(buf);
        skip_ws(&mut i);
        match chars.get(i) {
            Some(',') => i += 1,
            Some(']') => return Some(out),
            _ => return None,
        }
    }
}

fn read_hex4(chars: &[char], i: &mut usize) -> Option<u32> {
    let mut v = 0u32;
    for _ in 0..4 {
        let d = chars.get(*i)?.to_digit(16)?;
        v = v * 16 + d;
        *i += 1;
    }
    Some(v)
}

export!(Node);
